+			bounds = append(bounds, lineRange{lo: lo, hi: i + 1})
+			lo, running = i+1, 0
 		}
 	}
+	if lo < len(lines) {
+		bounds = append(bounds, lineRange{lo: lo, hi: len(lines)})
+	}
+	return bounds
+}

