2427		if strings.HasSuffix(treePath, ".jsonl") || strings.HasSuffix(treePath, ".json") {
2428			var (
2429				redacted redact.RedactedBytes
2430				err      error
2431			)
2432			if usePrivacyFilter {
2433				redacted, err = redact.JSONLBytesWithPrivacyFilter(ctx, content)
2434			} else {
2435				redacted, err = redact.JSONLBytes(content)
2436			}
2437			if err == nil {
2438				return redacted.Bytes()
2439			}
2440			// JSONL parse failed — fall through to plain bytes.
2441		}
2442		if usePrivacyFilter {
2443			return redact.BytesWithPrivacyFilter(ctx, content)
2444		}
2445		return redact.Bytes(content)
2446	}
