2448	// GetGitAuthorFromRepo retrieves the git user.name and user.email,
2449	// checking both the repository-local config and the global ~/.gitconfig.
2450	func GetGitAuthorFromRepo(repo *git.Repository) (name, email string) {
2451		// ConfigScoped merges local + global (local wins), matching git's own resolution.
2452		// Uses the ConfigLoader plugin registered in configloader.go (a symlink-following
2453		// Auto loader; importing go-git/v6/x/plugin registers go-git's default, which we
2454		// override there so global config behind a symlinked ~/.config is still read).
2455		if cfg, err := repo.ConfigScoped(config.GlobalScope); err == nil {
2456			name = cfg.User.Name
2457			email = cfg.User.Email
2458		}
2459	
2460		// If not found in local config, try global config
2461		if name == "" || email == "" {
2462			//nolint:staticcheck // the v6 is not yet released, revisit once it is.
2463			globalCfg, err := config.LoadConfig(config.GlobalScope)
2464			if err == nil {
2465				if name == "" {
2466					name = globalCfg.User.Name
2467				}
2468				if email == "" {
2469					email = globalCfg.User.Email
2470				}
2471			}
